#include "game_engine.hpp"
#include "game_feedback.hpp"
namespace remora {
float GameEngine::random(){random_^=random_<<13;random_^=random_>>17;random_^=random_<<5;return (random_>>8)/16777216.0f;}
int GameEngine::rnd(int n){return n>0?int(random()*n):0;}int GameEngine::key(){return 1+rnd(6);}
int GameEngine::stage()const{return std::max(0,s.level-1)/5;}int GameEngine::extra()const{return stage()/3;}int GameEngine::burden()const{return stage()/2;}bool GameEngine::hard()const{return s.difficulty>=2;}
float GameEngine::pace()const{return std::max(.55f,std::pow(.94f,float(stage())));}
void GameEngine::later(int ms,std::function<void()>fn){timers_.push_back({s.now+ms,order_++,std::move(fn)});}
void GameEngine::cancel(){timers_.clear();s.deadline=0;}
void GameEngine::deadline(int ms){s.window=ms;s.deadline=ms?s.now+ms:0;}
void GameEngine::advance(int ms){const auto end=s.now+ms;for(int guard=0;guard<1000;guard++){auto it=std::min_element(timers_.begin(),timers_.end(),[](const Timer&a,const Timer&b){return a.at==b.at?a.order<b.order:a.at<b.at;});if(it==timers_.end()||it->at>end)break;auto fn=it->fn;s.now=it->at;timers_.erase(it);fn();}s.now=end;if(s.deadline&&s.now>=s.deadline&&s.phase!=Phase::Over)fail("WAKTU HABIS");}
void GameEngine::shuffle(std::vector<int>&a){for(int i=int(a.size())-1;i>0;i--)std::swap(a[i],a[rnd(i+1)]);}
std::vector<int>GameEngine::pattern(int length,const std::vector<int>&prev){std::vector<int>a(length);for(auto &n:a)n=key();if(!prev.empty()&&a[0]==prev[0])a[0]=a[0]%6+1;return a;}
void GameEngine::refreshPalette(){auto old=s.palette;if(!hard()&&s.level!=1&&(s.level-1)%5!=0)return;if(!hard()&&s.level==1){std::copy(KeyColors,KeyColors+6,s.palette.begin());return;}std::vector<int>p={0,1,2,3,4,5};bool ok=false;for(int tries=0;tries<24;tries++){shuffle(p);ok=true;for(int i=0;i<6;i++)if(old[p[i]]==old[i]||old[p[i]]==KeyColors[i])ok=false;if(ok)break;}if(!ok)for(int shift=1;shift<6;shift++){ok=true;for(int i=0;i<6;i++){p[i]=(i+shift)%6;if(old[p[i]]==old[i]||old[p[i]]==KeyColors[i])ok=false;}if(ok)break;}for(int i=0;i<6;i++)s.palette[i]=old[p[i]];for(int&n:s.sequence){auto c=old[n-1];n=int(std::find(s.palette.begin(),s.palette.end(),c)-s.palette.begin())+1;}}
void GameEngine::points(int n){s.score+=n;}
void GameEngine::clear(){cancel();s.clears++;s.score+=100+s.level*10;s.phase=Phase::Clear;s.message=WinPhrases[s.mode][(s.clears-1)%15];s.pulse=0;if(sound)sound("clear");if(record&&s.mode!=2)record(s.mode,s.score,false);later(1450,[this]{nextLevel();});}
void GameEngine::fail(const char*reason){cancel();s.reason=reason;s.phase=Phase::Over;int tier=s.clears>=8||s.score>=1600?3:s.clears>=3||s.score>=600?2:s.clears>=1||s.score>=100?1:0;s.message=LossTitles[s.mode][tier];if(record&&s.mode!=2)record(s.mode,s.score,false);if(sound)sound("fail");}
void GameEngine::start(int mode,int difficulty,uint32_t seed){cancel();s=GameState{};s.mode=std::clamp(mode,0,GameCount-1);s.difficulty=std::clamp(difficulty,0,4);random_=seed?seed:37;std::copy(KeyColors,KeyColors+6,s.palette.begin());nextLevel();}
void GameEngine::nextLevel(){cancel();auto old=s;s=GameState{};s.mode=old.mode;s.difficulty=old.difficulty;s.level=old.level+1;s.score=old.score;s.clears=old.clears;s.now=old.now;s.palette=old.palette;s.sequence=std::move(old.sequence);s.recent=std::move(old.recent);refreshPalette();switch(s.mode){case 0:case 1:memory();break;case 2:reaction();break;case 3:maze();break;case 4:whack();break;case 5:potato();break;case 6:direction();break;case 7:missing();break;case 8:decoder();break;case 9:snake();break;case 10:pong();break;}}
void GameEngine::press(int n){if(n<1||n>6)return;switch(s.phase){case Phase::Input:memoryPress(n);break;case Phase::ReactionWait:case Phase::ReactionGo:case Phase::ReactionFake:reactionPress(n);break;case Phase::MazeInput:mazePress(n);break;case Phase::Whack:whackPress(n);break;case Phase::Potato:potatoPress(n);break;case Phase::DirectionInput:directionPress(n);break;case Phase::MissingInput:missingPress(n);break;case Phase::DecoderInput:decoderPress(n);break;case Phase::Snake:snakePress(n);break;case Phase::Pong:pongPress(n);break;default:break;}}
bool GameEngine::keyDown(int n){if(s.phase==Phase::Pong&&(n==1||n==3)){if(!s.held[n]){s.held[n]=true;press(n);}return true;}if(s.phase==Phase::Whack)for(size_t i=0;i<s.cues.size();i++){auto &c=s.cues[i];if(!c.done&&c.type==3&&c.target==n){if(c.holding)return true;c.holding=true;auto level=s.level,wave=s.round;later(s.difficulty>=3?(s.difficulty==4?750:700):650,[this,i,level,wave]{if(s.phase!=Phase::Whack||s.level!=level||s.round!=wave||i>=s.cues.size())return;auto &c=s.cues[i];if(!c.holding||c.done)return;c.done=true;points(30);if(sound)sound("correct");if(std::all_of(s.cues.begin(),s.cues.end(),[](auto &c){return c.done;}))whackComplete();});return true;}}return false;}
void GameEngine::keyUp(int n){if(n<1||n>6)return;s.held[n]=false;if(s.phase==Phase::Whack)for(auto&c:s.cues)if(c.type==3&&c.target==n&&c.holding){c.holding=false;if(!c.done)fail("HOLD TERLALU SINGKAT");return;}}
std::array<uint32_t,6>GameEngine::leds()const{std::array<uint32_t,6>a{};auto p=s.phase;auto put=[&](int n,uint32_t c){if(n>=1&&n<=6)a[n-1]=c;};if(p==Phase::Watch||p==Phase::MissingWatch||p==Phase::MissingReplay)put(s.pulse,s.pulse?s.palette[s.pulse-1]:0);else if(p==Phase::Input||p==Phase::MissingInput||p==Phase::DecoderInput)a=s.palette;else if(p==Phase::ReactionGo||p==Phase::ReactionFake)put(s.target,p==Phase::ReactionFake?0xff797d:s.palette[s.target-1]);else if(p==Phase::MazePreview||p==Phase::MazeInput){for(int n:{1,2,3,5}){int t=mazeTarget(n);put(n,t<0||!has(s.links[s.current],t)?0xff797d:s.portalFrom==t&&!s.portalUsed?0x79acfa:has(s.bonuses,t)&&!has(s.collected,t)?0xffd76b:s.palette[n-1]);}}else if(p==Phase::Whack){const uint32_t c[]={0x8bdcad,0xff797d,0x79acfa,0xffd76b,0xc49bef};for(auto&q:s.cues)if(!q.done)put(q.key,c[q.type]);}else if(p==Phase::Potato)put(s.signal,s.green?0x8bdcad:0xff797d);else if(p==Phase::DirectionPreview||p==Phase::DirectionInput){for(int n:s.mapping)put(n,s.palette[n-1]);}else if(p==Phase::DecoderWatch){if(s.bit>=0)put(s.signalKey,s.bit?0x8bdcad:0x79acfa);}else if(p==Phase::Snake){for(int n:{1,2,3,5})put(n,s.palette[n-1]);}else if(p==Phase::Pong){for(int n:{1,3})put(n,s.palette[n-1]);}return a;}
}
